 4:[['预测小差值与求和顺序的影响','Predict effects of cancellation and addition order'],['改变 x 的指数，比较直接式和稳定式','Change x exponent; compare direct and stable forms'],['记录两种表达式及两种求和顺序','Record both expressions and addition orders'],['解释误差来源并提出交叉核对办法','Explain error sources and cross-checks']],
 5:[['预测中点法幅值与相位的表现','Predict midpoint amplitude and phase behavior'],['固定圈数，逐次增加每圈步数','Fix revolution count and refine steps per revolution'],['记录两种方法的幅值、累计相位误差','Record amplitude and accumulated phase errors'],['用放大因子说明守恒与准确的区别','Use amplification factors to distinguish conservation from accuracy']],
 6:[['预测广播输出形状及峰值内存','Predict broadcast shape and peak memory'],['改变 m,n 与计时样本选择','Change m,n and timing-sample selection'],['记录输出元素数、字节数、中位数和均值','Record output elements, bytes, median and mean'],['指出不能公平比较的计时组','Identify timing groups that cannot be fairly compared']],
 7:[['预测光滑函数与窄峰的细化趋势','Predict refinement trends for smooth and peaked functions'],['选择四种函数，对比 N=4、8、16、64','Choose four functions; compare N=4,8,16,64'],['记录近似值、实际误差、估计误差和调用数','Record estimates, actual/estimated errors and calls'],['找出两次结果相同但积分不准的反例','Find agreeing grids with an inaccurate integral']],
 8:[['预测有扰动时减小步长的影响','Predict smaller-step behavior with perturbations'],['切换公式、边界与扰动幅度，扫描步长','Switch formulas, boundary and perturbation; scan h'],['记录目标导数、计算值及误差最低区域','Record target, computed derivative and low-error region'],['解释域外采样与噪声放大的限制','Explain domain constraints and perturbation amplification']],
 9:[['预测局部自适应在哪些区域增加节点','Predict where adaptive sampling concentrates'],['调整函数、容差、深度和调用预算','Adjust function, tolerance, depth and call budget'],['记录叶区间、调用数及终止状态','Record leaf intervals, calls and termination'],['对比估计误差与已知实际误差','Compare estimated and known actual error']],
10:[['预测样条连接处的导数连续性','Predict derivative continuity at spline knots'],['切换节点分布、导数阶数与外推范围','Switch nodes, derivative order and extrapolation range'],['记录节点二阶导数及三种方法的曲线','Record nodal curvatures and all three curves'],['区分自然边界与外推正确性','Distinguish natural boundaries from extrapolation correctness']],
11:[['预测曲率与权重对残差的影响','Predict curvature and weighting effects on residuals'],['对相同合成数据切换模型次数和权重','Switch degree and weights for identical data'],['记录系数、加权目标及残差形状','Record coefficients, weighted objective and residual structure'],['用综合任务比较插值、积分与拟合','Use the project to compare interpolation, integration and fitting']],
12:[['预测零主元与病态性的不同结果','Predict distinct effects of zero pivots and ill-conditioning'],['切换主元策略、右端项，逐步查看分解','Switch pivoting and RHS; inspect factorization steps'],['记录 PA−LU、解、残差及后向误差','Record PA−LU, solution, residual and backward error'],['说明复用分解与输入敏感性的区别','Explain factor reuse versus input sensitivity']],
13:[['预测停滞矩阵的非对角范数趋势','Predict the off-diagonal trend for a stagnating matrix'],['选择对称矩阵并逐步增加 QR 轮数','Choose a symmetric matrix and increase QR steps'],['记录当前矩阵、非对角范数及特征对残差','Record matrix, off-diagonal norm and eigenpair residual'],['解释预算耗尽为何不能标成收敛','Explain why budget exhaustion is not convergence']],
14:[['预测重根、循环初值和二分的差别','Predict multiple-root, cyclic-start and bisection behavior'],['切换函数与方法，逐步检查迭代历史','Switch function and method; inspect iteration history'],['记录残差、括区与停止原因','Record residual, bracket and stop reason'],['比较残差与根位置误差的含义','Compare residual and root-position error']],
